/**
 * Is the code running from a build output rather than a source checkout?
 *
 * Two markers, both server-side facts rather than anything a request can
 * influence:
 *
 *   - `VERCEL` is set by the platform on every serverless deployment.
 *   - `server.js` sits at the root of a Next `output: "standalone"` tree and is
 *     generated by the build. A checkout does not have one, and the standalone
 *     server `process.chdir()`s to that root before listening — so finding it at
 *     `process.cwd()` is the same as being inside one. Every host that runs the
 *     Docker image (Compose, Coolify, Dokploy, Render, Railway, and
 *     `npm run docker:prod`) is one.
 *
 * Two rules key on it. A built deployment cannot register extensions
 * (`checkInstallable` in src/lib/repository/install.ts), and it searches only
 * mixos.org or a catalogue on its own machine (`repositoryBaseUrl` in
 * src/lib/repository/client.ts).
 *
 * Deliberately NOT `NODE_ENV`, which says how the code was compiled, not where
 * it runs from.
 */

import { existsSync } from "fs";
import path from "path";

// Looked for once, at module load: a standalone tree cannot appear under a
// running server, and a per-call `stat` would put a filesystem hit in front of
// every render of the browse page to answer a constant.
const STANDALONE_SERVER = existsSync(path.join(process.cwd(), "server.js"));

export function isBuiltDeployment(): boolean {
  return Boolean(process.env.VERCEL) || STANDALONE_SERVER;
}

/**
 * What a built deployment says when it is asked to install or register an
 * extension. It isn't a fault, so it reads as information, not as a warning: a
 * deployment runs what its build carries, and an extension reaches it through
 * a checkout, a commit and a deploy.
 */
export const BUILT_DEPLOYMENT_NOTICE =
  "This deployment runs a build. Install and register in a checkout of your repository, commit, and deploy.";
